H.background();
const w = H.W, h = H.H;
const A1 = Math.max(0.5, P.a1), A2 = Math.max(0.2, P.a2), v1 = Math.max(0.1, P.v1);
const v2 = v1 * A1 / A2;
const Q = A1 * v1;
const cy = h * 0.52;
const xL = w * 0.1, xM1 = w * 0.42, xM2 = w * 0.58, xR = w * 0.9;
const s = 14;
const r1 = A1 * s, r2 = A2 * s;
const pipe = [
  [xL, cy - r1], [xM1, cy - r1], [xM2, cy - r2], [xR, cy - r2],
  [xR, cy + r2], [xM2, cy + r2], [xM1, cy + r1], [xL, cy + r1]
];
H.path(pipe, { color: H.colors.axis, width: 2.5, fill: "#13314f", close: true });
const nLanes = 5;
for (let j = 0; j < nLanes; j++) {
  const yfrac = (j + 0.5) / nLanes - 0.5;
  const nDots = 6;
  for (let k = 0; k < nDots; k++) {
    const phase = ((t * v1 * 0.25 + k / nDots) % 1);
    let x, vloc, rloc;
    if (phase < 0.45) {
      const f = phase / 0.45;
      x = xL + (xM1 - xL) * f;
      rloc = r1; vloc = v1;
    } else if (phase < 0.55) {
      const f = (phase - 0.45) / 0.1;
      x = xM1 + (xM2 - xM1) * f;
      rloc = r1 + (r2 - r1) * f; vloc = v1 + (v2 - v1) * f;
    } else {
      const f = (phase - 0.55) / 0.45;
      x = xM2 + (xR - xM2) * f;
      rloc = r2; vloc = v2;
    }
    const y = cy + yfrac * 2 * rloc;
    H.circle(x, y, 3, { fill: H.colors.accent });
  }
}
H.arrow(xL + 30, cy - r1 - 14, xL + 30 + 18 * (v1 / 3), cy - r1 - 14, { color: H.colors.good, width: 2 });
H.arrow(xR - 30 - 18 * (v2 / 3), cy + r2 + 14, xR - 30, cy + r2 + 14, { color: H.colors.warn, width: 2 });
H.text("A1, v1", xL + 6, cy - r1 - 8, { color: H.colors.sub, size: 12 });
H.text("A2, v2", xR - 56, cy + r2 + 26, { color: H.colors.sub, size: 12 });
H.text("Continuity equation", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("A1 v1 = A2 v2 = Q", 24, 52, { color: H.colors.sub, size: 13 });
H.text("v2 = v1 A1/A2 = " + v2.toFixed(2) + " m/s", 24, 74, { color: H.colors.accent, size: 15, weight: 700 });
H.text("Q = " + Q.toFixed(2) + " m3/s  (constant)", 24, 96, { color: H.colors.sub, size: 13 });
